final case class MonsterType(id: String, baseHealth: Int, attack: String) {
  def newMonster(): Monster = new Monster(this)
}

final class Monster(val kind: MonsterType) {
  var health: Int = kind.baseHealth
}

def registry(types: List[MonsterType]): Map[String, MonsterType] =
  types.map(t => t.id -> t).toMap   // id -> descriptor, loaded from data
